import * as React from "react";
import { mount, ReactWrapper } from "enzyme";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";

import { createTestClient, mkEvent, mkStubRoom, stubClient } from "../../../test-utils";
import MessageComposer from "../../../../src/components/views/rooms/MessageComposer";
import MatrixClientContext from "../../../../src/contexts/MatrixClientContext";
import { MatrixClientPeg } from "../../../../src/MatrixClientPeg";
import RoomContext from "../../../../src/contexts/RoomContext";
import { IRoomState } from "../../../../src/components/structures/RoomView";
import ResizeNotifier from "../../../../src/utils/ResizeNotifier";
import { RoomPermalinkCreator } from "../../../../src/utils/permalinks/Permalinks";

describe("MessageComposer", () => {
    stubClient();
    const cli = createTestClient();
    const room = mkStubRoom("!roomId:server", "Room 1", cli);

    it("Renders a SendMessageComposer and MessageComposerButtons by default", () => {
        const wrapper = wrapAndRender({ room });

        expect(wrapper.find("SendMessageComposer")).toHaveLength(1);
        expect(wrapper.find("MessageComposerButtons")).toHaveLength(1);
    });

    it("Does not render a SendMessageComposer or MessageComposerButtons when user has no permission", () => {
        const wrapper = wrapAndRender({ room }, false);

        expect(wrapper.find("SendMessageComposer")).toHaveLength(0);
        expect(wrapper.find("MessageComposerButtons")).toHaveLength(0);
        expect(wrapper.find(".mx_MessageComposer_noperm_error")).toHaveLength(1);
    });

    it("Does not render a SendMessageComposer or MessageComposerButtons when room is tombstoned", () => {
        const wrapper = wrapAndRender({ room }, true, mkEvent({
            event: true,
            type: "m.room.tombstone",
            room: room.roomId,
            user: "@user1:server",
            skey: "",
            content: {},
            ts: Date.now(),
        }));

        expect(wrapper.find("SendMessageComposer")).toHaveLength(0);
        expect(wrapper.find("MessageComposerButtons")).toHaveLength(0);
        expect(wrapper.find(".mx_MessageComposer_roomReplaced_header")).toHaveLength(1);
    });
});

function wrapAndRender(props = {}, canSendMessages = true, tombstone?: MatrixEvent): ReactWrapper {
    const mockClient = MatrixClientPeg.get();
    const roomId = "myroomid";
    const room: any = {
        currentState: undefined,
        roomId,
        client: mockClient,
        getMember: function(userId: string): RoomMember {
            return new RoomMember(roomId, userId);
        },
    };

    const roomState = {
        room, canSendMessages, tombstone,
    } as unknown as IRoomState;

    const defaultProps = {
        room,
        resizeNotifier: new ResizeNotifier(),
        permalinkCreator: new RoomPermalinkCreator(room),
    };

    return mount(
        <MatrixClientContext.Provider value={mockClient}>
            <RoomContext.Provider value={roomState}>
                <MessageComposer {...defaultProps} {...props} />
            </RoomContext.Provider>
        </MatrixClientContext.Provider>,
    );
}

    private onAction = (payload: ActionPayload) => {
        if (!this.editorRef.current) return;

        if (payload.action === Action.ComposerInsert) {
            if (payload.timelineRenderingType !== this.context.timelineRenderingType) return;
            if (payload.composerType !== ComposerType.Edit) return;

            if (payload.userId) {
                this.editorRef.current?.insertMention(payload.userId);
            } else if (payload.event) {
                this.editorRef.current?.insertQuotedMessage(payload.event);
            } else if (payload.text) {
                this.editorRef.current?.insertPlaintext(payload.text);
            }
        } else if (payload.action === Action.FocusEditMessageComposer) {
            this.editorRef.current.focus();
        }
    };

    render() {
        return (<div className={classNames("mx_EditMessageComposer", this.props.className)} onKeyDown={this.onKeyDown}>
            <BasicMessageComposer
                ref={this.editorRef}
                model={this.model}
                room={this.getRoom()}
                threadId={this.props.editState?.getEvent()?.getThread()?.id}
                initialCaret={this.props.editState.getCaret()}
                label={_t("Edit message")}
                onChange={this.onChange}
            />
            <div className="mx_EditMessageComposer_buttons">
                <AccessibleButton kind="secondary" onClick={this.cancelEdit}>
                    { _t("Cancel") }
                </AccessibleButton>
                <AccessibleButton kind="primary" onClick={this.sendEdit} disabled={this.state.saveDisabled}>
                    { _t("Save") }
                </AccessibleButton>
            </div>
        </div>);
    }
}

